$server=Db::connect($config,false);$server->exec('DROP DATABASE IF EXISTS `'.$db.'`');$server->exec('CREATE DATABASE `'.$db.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$pdo=Db::connect($config);Db::useConnection($pdo,$config);
try{
    foreach(explode(';',file_get_contents(__DIR__.'/../app/schema.sql')) as $sql){if(trim($sql)!==''){$pdo->exec($sql);}}
