    foreach(['home'=>1000,'resource'=>256,'stronghold'=>64] as $kind=>$count){checkWorld((int)$pdo->query("SELECT COUNT(*) FROM world_sites WHERE kind='$kind'")->fetchColumn()===$count,'initial '.$kind.' count');}
    $homes=$pdo->query("SELECT id,q,r,home_user_id FROM world_sites WHERE kind='home' ORDER BY id")->fetchAll();$bases=$pdo->query('SELECT user_id,SHA2(state_json,256) AS digest FROM bases ORDER BY user_id')->fetchAll();
    Db::transaction(fn(PDO $pdo)=>World::initialize($pdo));checkWorld($homes===$pdo->query("SELECT id,q,r,home_user_id FROM world_sites WHERE kind='home' ORDER BY id")->fetchAll(),'stable idempotent homes');checkWorld($bases===$pdo->query('SELECT user_id,SHA2(state_json,256) AS digest FROM bases ORDER BY user_id')->fetchAll(),'initializer never modifies yards');
    $u=Game::register('World Tester','correct-local-password');$id=$u['id'];$home=World::home($id);checkWorld($home!==null&&$home['owner_id']===$id,'registration atomically allocates home');checkWorld((int)$pdo->query('SELECT COUNT(DISTINCT CONCAT(q,CHAR(44),r)) FROM world_sites')->fetchColumn()===(int)$pdo->query('SELECT COUNT(*) FROM world_sites')->fetchColumn(),'unique map occupancy including Fortification cells');
    $map=World::map($id);checkWorld($map['center']===['q'=>$home['q'],'r'=>$home['r']],'default map centers own home');$ownMarker=array_values(array_filter($map['sites'],fn($site)=>$site['id']===$home['id']))[0];checkWorld($ownMarker['shield_until']>time(),'map shows actual home protection');$homeView=World::site($id,$home['id']);checkWorld(!$homeView['canAttack']&&$homeView['site']['homeUserId']===$id,'home marker delegates ordinary visit with self attack blocked');checkWorld($map['mapRoomLevel']===0&&$map['holdingLimit']===0,'no gifted Map Room');
    $map=World::map($id,['radius'=>900]);checkWorld(count($map['sites'])<=469,'bounded radius map');foreach($map['sites'] as $s){checkWorld(!isset($s['state'],$s['garrison'],$s['resources']),'map summaries keep inventory private');checkWorld(World::distance($home['q'],$home['r'],$s['q'],$s['r'])<=12,'radius clamp exact hex');}
    rejectWorld(fn()=>World::map($id,['q'=>[]]),'array map input');rejectWorld(fn()=>World::map($id,['q'=>64]),'out of map center');
    $candidates=World::candidates($id,24,100);checkWorld(count($candidates)>0&&count($candidates)<=24,'bounded nearby neutral candidates');$site=$candidates[0];$siteId=$site['id'];
    $view=World::site($id,$siteId);checkWorld($view['management']===null&&$view['base']['garrison']===[]&&$view['base']['owner']['id']===0,'neutral view private and has no user account');checkWorld(!$view['canAttack']&&str_contains($view['attackReason'],'Map Room'),'authoritative Map Room gate');
    rejectWorld(fn()=>Game::mutate($id,'build',['type'=>'outpost','x'=>27,'y'=>28]),'site core cannot be built at home');
    $b=Game::loadBase($id);$b['buildings'][0]['level']=3;$b['buildings'][0]['hp']=$b['buildings'][0]['max_hp']=Game::buildingStats('townhall',3)['max_hp'];$b['resources']=array_fill_keys(['twig','pebble','putty','goo'],30000);Game::saveBase($id,$b);
    [$roomX,$roomY]=Bots::placements($id,'maproom',0,$b,Catalog::buildings()['maproom'])[0];
    Game::mutate($id,'build',['type'=>'maproom','x'=>$roomX,'y'=>$roomY]);$b=Game::loadBase($id);$mr=array_values(array_filter($b['buildings'],fn($x)=>$x['type']==='maproom'))[0];checkWorld($b['resources']['twig']===24000,'Map Room paid from actual resources');checkWorld($mr['level']===0&&$mr['ready_at']>time(),'Map Room has construction time');rejectWorld(fn()=>World::assertAttack($id,$b,$site),'unfinished Map Room gate');
    foreach($b['buildings'] as &$building){if($building['type']==='maproom'){$building['ready_at']=time()-1;}}unset($building);Game::accrue($b,time());Game::saveBase($id,$b);World::assertAttack($id,$b,$site);checkWorld(true,'completed Map Room enables reachable invasion');rejectWorld(fn()=>Game::mutate($id,'build',['type'=>'maproom','x'=>27,'y'=>5]),'one Map Room only');
    Db::transaction(function() use($id,$siteId):void{$b=Game::loadBase($id,true);Game::accrue($b,time());$site=World::load($siteId,true);$bases=[$id=>$b];World::capture($site,$id,$bases,time());Game::saveBase($id,$bases[$id]);});
    $owned=World::load($siteId);checkWorld($owned['owner_id']===$id&&$owned['state']['garrison']===[],'capture transfers and clears neutral garrison');checkWorld($owned['state']['shield_until']>time()&&$owned['state']['repair_at']>time(),'capture protects and rebuilds');rejectWorld(fn()=>World::mutate($id,'worldGarrison',['siteId'=>$siteId,'type'=>'pokey','quantity'=>1]),'rebuilding blocks garrison');
    $owned['state']['repair_at']=time()-1;$owned['state']['shield_until']=0;World::save($owned);$view=World::site($id,$siteId);checkWorld($view['management']!==null&&$view['management']['ready_at']===0,'owner management completes rebuild');checkWorld($view['management']['upgrade']['benefits']['range']>=$view['management']['benefits']['range'],'owner sees quoted next level benefits');
    $beforeArmy=Game::loadBase($id)['army']['pokey'];World::mutate($id,'worldGarrison',['siteId'=>$siteId,'type'=>'pokey','quantity'=>3]);checkWorld(Game::loadBase($id)['army']['pokey']===$beforeArmy-3,'garrison deducts actual ready army');$g=World::site($id,$siteId)['management'];checkWorld($g['garrison']['pokey']===3,'garrison persists');World::mutate($id,'worldUngarrison',['siteId'=>$siteId,'type'=>'pokey','quantity'=>2]);checkWorld(Game::loadBase($id)['army']['pokey']===$beforeArmy-1,'ungarrison conserves inventory');
    rejectWorld(fn()=>World::mutate($id,'worldGarrison',['siteId'=>$siteId,'type'=>'pokey','quantity'=>[]]),'strict transfer quantity');rejectWorld(fn()=>World::mutate(1,'worldAbandon',['siteId'=>$siteId]),'non owner cannot abandon');
    $cost=World::siteStats($owned['kind'],1)['upgradeCost'];$before=Game::loadBase($id);World::mutate($id,'worldUpgrade',['siteId'=>$siteId]);$after=Game::loadBase($id);checkWorld(abs($before['resources']['twig']-$after['resources']['twig']-$cost['twig'])<1,'site upgrade pays real resources');$owned=World::load($siteId);checkWorld($owned['state']['upgrade_to']===2,'paid upgrade target persists');rejectWorld(fn()=>World::mutate($id,'worldUpgrade',['siteId'=>$siteId]),'duplicate upgrade blocked');
    $owned['state']['ready_at']=time()-50;World::save($owned);$after['last_tick']=time()-100;$after['resources']=array_fill_keys(['twig','pebble','putty','goo'],0);$after['world']['pending']=$owned['kind']==='resource'?[['ready_at'=>$owned['state']['ready_at'],'resourcePerSecond'=>.1,'capacity'=>4000]]:[];Game::saveBase($id,$after);$view=World::site($id,$siteId);checkWorld($view['site']['level']===2&&$view['management']['ready_at']===0,'upgrade lazy completion persisted');if($owned['kind']==='resource'){checkWorld(abs(Game::loadBase($id)['resources']['twig']-7.5)<.25,'income splits upgrade boundary exactly');}
    $owned=World::load($siteId);$owned['state']['buildings'][1]['hp']=0;World::save($owned);$b=Game::loadBase($id);$b['resources']=array_fill_keys(['twig','pebble','putty','goo'],30000);Game::saveBase($id,$b);$quote=World::repairCost($owned);World::mutate($id,'worldRepair',['siteId'=>$siteId]);checkWorld(World::load($siteId)['state']['repair_at']>time(),'paid repair starts timer');checkWorld(abs(Game::loadBase($id)['resources']['twig']-(30000-$quote['twig']))<1,'repair charges actual quote');
    World::mutate($id,'worldAbandon',['siteId'=>$siteId]);$owned=World::load($siteId);checkWorld($owned['owner_id']===null&&$owned['state']['garrison']===[],'abandon clears owner and garrison');checkWorld(Game::loadBase($id)['world']['holdings']===0,'abandon recomputes cached holdings');checkWorld(Game::loadBase($id)['army']['pokey']===$beforeArmy-1,'abandon grants no garrison refund');
    $pdo->exec("UPDATE settings SET value='1' WHERE name='schema_version'");rejectWorld(fn()=>World::assertSchema(),'schema1 fails clearly');$pdo->exec("UPDATE settings SET value='3' WHERE name='schema_version'");
    // Fill the finite map without adding users, then verify registration continues into a frontier region.
    $pdo->exec('CREATE TEMPORARY TABLE occupied_before_full AS SELECT id FROM world_sites');$occupied=[];foreach($pdo->query('SELECT q,r FROM world_sites')->fetchAll() as $row){$occupied[$row['q'].','.$row['r']]=true;}$insert=$pdo->prepare("INSERT INTO world_sites(kind,q,r,name,updated_at) VALUES('resource',?,?,'Test full-map sentinel',?)");foreach(range(0,63) as $q){foreach(range(0,63) as $r){if(!isset($occupied[$q.','.$r])){$insert->execute([$q,$r,time()]);}}}
    $users=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$baseCount=(int)$pdo->query('SELECT COUNT(*) FROM bases')->fetchColumn();$overflow=Game::register('Map Full Tester','correct-local-password');checkWorld(Regions::id(World::home($overflow['id'])['q'])===2,'full legacy region finds a free frontier landing');checkWorld((int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()===$users+1&&(int)$pdo->query('SELECT COUNT(*) FROM bases')->fetchColumn()===$baseCount+1,'overflow registration commits exactly one account, yard and home');
    echo "World database tests passed: {$checks} assertions on ".$pdo->query('SELECT VERSION()')->fetchColumn().".\n";
}finally{$server->exec('DROP DATABASE IF EXISTS `'.$db.'`');}
